/* Tekrar havuzu: con-contrast, con-cause, con-result, con-purpose, con-correlative, con-time */
PRACTICE.push(
  {id:"r-con-contrast-01", sub:"con-contrast", from:["conj-01"], q:"---- the city's population has doubled since 1990, the number of public hospitals has remained almost unchanged.", o:["Despite","Because of","Although","Unless","In case"], a:2, e:"Although + cümle = -e rağmen; nüfus ikiye katlanırken hastane sayısının değişmemesi beklentiye ters düşer. Despite da zıtlık bildirir ama ardından özne + yüklem değil isim öbeği gelmelidir."},
  {id:"r-con-contrast-02", sub:"con-contrast", from:["conj-02"], q:"---- the heavy snowfall, the marathon went ahead as planned.", o:["In spite of","Although","Even though","Because of","Whereas"], a:0, e:"In spite of + isim öbeği (the heavy snowfall) = -e rağmen. Although ve Even though da zıtlık bildirir ama ardından cümle ister; Because of ise karın maratonun yapılmasının sebebi olduğunu söyler."},
  {id:"r-con-contrast-03", sub:"con-contrast", from:["conj-03"], q:"Mammals maintain a constant body temperature, ---- reptiles depend largely on their surroundings to regulate their body heat.", o:["so that","because","therefore","in case","whereas"], a:4, e:"whereas = oysa, -iken; memeliler ile sürüngenler karşılaştırılıyor. because sürüngenlerin durumunu memelilerin sebebi yapar; therefore ise virgülle iki cümleyi bağlayamaz ve sonuç bildirir."},
  {id:"r-con-contrast-04", sub:"con-contrast", from:["conj-04"], q:"The company's profits rose by 12 percent last year; ----, it announced plans to close two of its factories.", o:["therefore","nonetheless","as a result","for example","likewise"], a:1, e:"nonetheless = yine de; kâr artarken fabrika kapatmak beklentiye aykırıdır. therefore ve as a result kâr artışını kapanışın sebebi gibi gösterir, bu mantıksızdır."},
  {id:"r-con-contrast-05", sub:"con-contrast", from:["w2-05","conj-01"], q:"---- online shopping offers consumers greater convenience, it has also contributed to the decline of many small local shops.", o:["Because","As soon as","So that","While","Unless"], a:3, e:"While + cümle = -mesine karşın; olumlu (kolaylık) ve olumsuz (küçük dükkânların gerilemesi) etkiler karşılaştırılıyor. Because ikinci cümleyi birincinin doğrudan sonucu yapar, oysa “also” bir karşı etkiyi vurgular."},
  {id:"r-con-contrast-06", sub:"con-contrast", from:["w2-11"], q:"Supporters of nuclear power point to its low carbon emissions; ----, critics emphasise the unsolved problem of radioactive waste, ---- the debate is far from settled.", o:["on the other hand / so","similarly / because","as a result / unless","in addition / although","for example / whereas"], a:0, e:"İki zıt görüş on the other hand ile bağlanır; görüşlerin çatışması tartışmanın bitmemesine yol açtığı için ikinci boşluğa so gelir. similarly iki görüşü benzer gösterir, oysa destekçiler ve eleştirmenler zıt düşünür."},
  {id:"r-con-contrast-07", sub:"con-contrast", from:["w3-01","conj-04"], passage:"For decades, doctors advised patients with chronic back pain to rest in bed as much as possible, believing that movement would only make the injury worse. (1) ----, recent research indicates that gentle movement and regular exercise usually lead to faster recovery than bed rest. Studies have shown that patients who stay active experience less pain and return to work sooner. As a result, many physiotherapists now design programmes that keep patients moving from the earliest stages of treatment.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["As a result","For example","Likewise","In contrast","Furthermore"], a:3, e:"Eski öneri (yatak istirahati) ile yeni bulgu (hareket daha iyi) birbirine zıttır: In contrast. As a result yeni bulguyu eski önerinin sonucu gibi, Likewise ise iki görüşü benzer gösterir."},
  {id:"r-con-contrast-08", sub:"con-contrast", from:["conj-02"], q:"---- being one of the richest countries in the world, the nation still has high levels of child poverty in some regions.", o:["Although","Despite","Because of","Even though","Whereas"], a:1, e:"Despite + V-ing (being) = -mesine rağmen. Although, Even though ve Whereas ardından özne + yüklem ister, V-ing alamaz; Because of ise zenginliği yoksulluğun sebebi yapar."},
  {id:"r-con-contrast-09", sub:"con-contrast", from:["conj-02","conj-01"], q:"---- the fact that the bridge had been inspected only a month earlier, engineers found serious cracks in its main supports.", o:["Although","Because of","Even if","Whereas","Despite"], a:4, e:"Despite the fact that + cümle = -mesine rağmen; kısa süre önce denetlenmiş köprüde çatlak bulunması beklenmedik bir durumdur. Although “the fact that” gibi bir isim öbeğinin önüne gelemez; Because of ise denetimi çatlakların sebebi yapar."},
  {id:"r-con-contrast-10", sub:"con-contrast", from:["conj-03"], q:"The first experiment produced promising results, ---- the second, which was conducted under stricter conditions, failed to confirm them.", o:["so","since","while","in case","as long as"], a:2, e:"while = oysa, -iken; iki deneyin zıt sonuçları karşılaştırılıyor. so ikinci deneyin başarısızlığını birincinin başarısına bağlar, since ise mantıksız bir sebep ilişkisi kurar."},
  {id:"r-con-contrast-11", sub:"con-contrast", from:["conj-01"], q:"Even though ----, the team managed to finish the project ahead of schedule.", o:["the client had provided a generous budget and clear instructions","the project manager was highly experienced","all the necessary equipment arrived on time","the team worked long hours every day","several key members left the company halfway through"], a:4, e:"Even though zıtlık ister; kilit üyelerin ayrılmasına rağmen projenin erken bitmesi beklenmedik bir durumdur. Cömert bütçe, deneyimli yönetici veya uzun çalışma saatleri başarıyı destekleyen, yani sebep niteliğindeki bilgilerdir."},
  {id:"r-con-contrast-12", sub:"con-contrast", from:["conj-04"], q:"Some critics dismissed the novel as too long and complicated; ----, it went on to win several major literary prizes.", o:["consequently","nevertheless","for instance","in other words","likewise"], a:1, e:"nevertheless = yine de; eleştirilmesine rağmen ödül kazanması zıtlıktır. consequently eleştiriyi ödüllerin sebebi yapar, in other words ise iki cümleyi aynı anlamda gösterir."},
  {id:"r-con-contrast-13", sub:"con-contrast", from:["conj-01"], q:"Though ----, the painting is now considered one of the artist's finest works.", o:["it has been displayed in many major museums","art historians have always praised its use of colour","it was largely ignored by critics when it was first exhibited","it attracts thousands of visitors every year","it was painted during the artist's most productive period"], a:2, e:"Though zıtlık kurar: ilk sergilendiğinde görmezden gelinen tablonun bugün başyapıt sayılması beklentiye aykırıdır. Diğer seçenekler tablonun değerini destekleyen bilgilerdir; zıtlık değil uyum oluştururlar."},
  {id:"r-con-contrast-14", sub:"con-contrast", from:["w3-01","conj-04"], q:"In some cultures, direct eye contact is seen as a sign of honesty; in others, ----, it may be regarded as disrespectful.", o:["however","therefore","similarly","for this reason","in addition"], a:0, e:"however = ancak; iki kültürdeki zıt yorumları bağlar. similarly iki yorumu benzer gösterir, therefore/for this reason ise birinci kültürdeki yorumu ikincisinin sebebi yapar."},
  {id:"r-con-contrast-15", sub:"con-contrast", from:["conj-01"], q:"---- the new smartphone is more expensive than its rivals, it has sold more units than any other model this year.", o:["Because","In spite of","As","Even though","So that"], a:3, e:"Even though + cümle = -mesine rağmen; pahalı olmasına karşın çok satması zıtlıktır. In spite of da zıtlık bildirir ama ardından cümle alamaz; Because ve As ise pahalılığı satışların sebebi yapar."},
  {id:"r-con-contrast-16", sub:"con-contrast", from:["conj-03","conj-02"], q:"Urban areas generally offer more job opportunities, ---- rural areas tend to provide a lower cost of living.", o:["despite","while","in spite of","because of","so that"], a:1, e:"while + cümle = -iken, oysa; kent ve kırın farklı avantajları karşılaştırılıyor. despite ve in spite of da zıtlık bildirir ama edat oldukları için ardından özne + yüklem (rural areas tend) gelemez."},
  {id:"r-con-contrast-17", sub:"con-contrast", from:["conj-02","conj-04"], q:"The drug reduced symptoms in most patients. ---- this, regulators refused to approve it because of concerns about its long-term safety.", o:["Although","Because of","Owing to","Whereas","In spite of"], a:4, e:"In spite of this = buna rağmen; ilacın etkili olması ile onaylanmaması zıtlıktır. Because of ve Owing to etkinliği reddin sebebi yapar; Although ve Whereas ise “this” gibi bir zamirin önüne gelemez, cümle ister."},
  {id:"r-con-contrast-18", sub:"con-contrast", from:["conj-01","conj-03"], q:"---- it lacks natural resources, Singapore has become one of the wealthiest countries in the world, ---- many resource-rich nations remain poor.", o:["Although / whereas","Because / so that","Despite / while","Since / therefore","Unless / because"], a:0, e:"Kaynak yokluğuna rağmen zenginleşme Although ile, Singapur ile kaynak zengini ülkelerin karşılaştırılması whereas ile verilir. Despite / while anlamca yakın görünse de Despite ardından cümle (it lacks) alamaz."},
  {id:"r-con-contrast-19", sub:"con-contrast", from:["w3-01","conj-02"], passage:"Electric cars produce no exhaust emissions, which makes them an attractive option for cities struggling with air pollution. (1) ---- these clear benefits, they are not entirely free of environmental costs. Mining the lithium and cobalt needed for their batteries can damage ecosystems and consume huge amounts of water. Moreover, if the electricity used to charge them comes from coal-fired power stations, their overall carbon footprint may be considerably larger than many buyers assume.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["Although","Because of","Despite","Instead of","Due to"], a:2, e:"Despite + isim öbeği (these clear benefits); faydalara rağmen çevresel maliyetlerin olması zıtlıktır. Although da zıtlık bildirir ama ardından cümle gerekir; Because of ve Due to ise faydaları maliyetlerin sebebi yapar."},
  {id:"r-con-contrast-20", sub:"con-contrast", from:["conj-03"], q:"Whereas ----, the younger generation increasingly prefers to rent.", o:["rents have risen sharply in most large cities","young people often move from city to city for work","house prices are much higher than they were in the past","earlier generations saw home ownership as a key sign of success","many young people cannot afford a deposit"], a:3, e:"Whereas iki grubu karşılaştırır: önceki kuşaklar ev sahibi olmayı önemserken genç kuşak kiralamayı seçiyor. Diğer seçenekler kiralamanın sebeplerini verir; karşılaştırma değil sebep ilişkisi kurar."},
  {id:"r-con-contrast-21", sub:"con-contrast", from:["conj-04"], q:"The law was intended to protect small farmers; in practice, ----, it mainly benefited large agricultural corporations.", o:["therefore","besides","likewise","though","so"], a:3, e:"Cümle ortasında zarf olarak kullanılan though = ancak, yine de; amaç ile uygulamadaki sonuç birbirine zıttır. therefore ve so amaçtan beklenen doğal sonucu anlatır, oysa sonuç amaca terstir."},
  {id:"r-con-contrast-22", sub:"con-contrast", from:["conj-01","conj-02"], q:"---- rich in vitamins, the fruit is rarely eaten in the region because of its bitter taste.", o:["Despite","Since","Although","In spite of","Unless"], a:2, e:"Although (it is) rich in vitamins = vitamin açısından zengin olmasına rağmen; although'dan sonra özne ve be fiili düşebilir. Despite ve In spite of sıfatın (rich) önüne gelemez, isim veya V-ing ister; Since ise zıtlığı sebebe çevirir."},
  {id:"r-con-contrast-23", sub:"con-contrast", from:["conj-04"], q:"The two languages share a common origin; ----, speakers of one cannot easily understand the other.", o:["nonetheless","hence","similarly","in other words","accordingly"], a:0, e:"nonetheless = yine de; ortak kökene rağmen birbirini anlayamamak beklentiye aykırıdır. hence ve accordingly ortak kökeni anlaşılmazlığın sebebi yapar, similarly ise zıtlığı görmez."},
  {id:"r-con-contrast-24", sub:"con-contrast", from:["conj-03"], q:"Some patients recover within a few days, ---- others suffer from symptoms for several months.", o:["because of","despite","so that","as a result","whereas"], a:4, e:"whereas + cümle = oysa; iki hasta grubu karşılaştırılıyor. despite ve because of edattır, ardından cümle (others suffer) alamaz; as a result ise yanlış bir sebep-sonuç ilişkisi kurar."},
  {id:"r-con-contrast-25", sub:"con-contrast", from:["conj-01","conj-04"], q:"---- hard the engineers tried, they could not stop the leak from spreading.", o:["Although","However","Despite","Whatever","Even though"], a:1, e:"However + sıfat/zarf = ne kadar … -se de (However hard they tried). Although ve Even though ardından doğrudan “hard” gibi bir zarf alıp özneye geçemez; Whatever ise isimle kullanılır, sıfat/zarfla kullanılmaz."},
  {id:"r-con-contrast-26", sub:"con-contrast", from:["w3-01","conj-01"], passage:"Many people believe that multitasking allows them to get more work done in less time. Psychological research, however, suggests the opposite. (1) ---- people feel highly productive when they switch rapidly between tasks, they actually make more mistakes and take longer to complete each task than when they focus on one thing at a time. Experts therefore advise workers to turn off notifications and to set aside uninterrupted periods for demanding work.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["Despite","Because","Although","Unless","In case"], a:2, e:"Although + cümle = -mesine rağmen; kendini verimli hissetmek ile daha çok hata yapmak zıtlıktır. Despite da zıtlık bildirir ama ardından cümle (people feel) alamaz; Because ise verimlilik hissini hataların sebebi yapar."},
  {id:"r-con-contrast-27", sub:"con-contrast", from:["conj-02"], q:"---- their low cost and convenience, plastic bags are being banned in a growing number of countries.", o:["Notwithstanding","Although","Because of","Thanks to","Whereas"], a:0, e:"Notwithstanding + isim öbeği = -e rağmen (despite ile aynı). Although ve Whereas ardından cümle ister; Because of ve Thanks to ise ucuzluğu yasakların sebebi gibi gösterir."},
  {id:"r-con-cause-01", sub:"con-cause", from:["conj-05"], q:"---- the demand for electric vehicles has grown so quickly, battery manufacturers are struggling to keep up.", o:["Although","Despite","Unless","Since","So that"], a:3, e:"Since + cümle = -dığı için; talebin hızla artması üreticilerin yetişememesinin sebebidir. Although zıtlık kurar, Despite ise ardından cümle alamaz."},
  {id:"r-con-cause-02", sub:"con-cause", from:["conj-06"], q:"The concert was cancelled ---- the singer's sudden illness.", o:["because","because of","since","as","although"], a:1, e:"because of + isim öbeği (the singer's sudden illness) = yüzünden. because, since ve as da sebep bildirir ama ardından özne + yüklem içeren bir cümle gerekir."},
  {id:"r-con-cause-03", sub:"con-cause", from:["conj-07"], q:"---- prices had risen sharply, many families were forced to cut back on heating during the winter.", o:["As","Owing to","Despite","In case","Due to"], a:0, e:"As + cümle = -dığı için; fiyat artışı ısınmadan kısmanın sebebidir. Owing to ve Due to da sebep bildirir ama edat oldukları için ardından cümle (prices had risen) alamaz."},
  {id:"r-con-cause-04", sub:"con-cause", from:["w2-06","conj-06"], q:"The ancient city was eventually abandoned, probably ---- a series of severe earthquakes.", o:["in spite of","instead of","as a result of","in case of","apart from"], a:2, e:"as a result of + isim = sonucunda, yüzünden; depremler şehrin terk edilmesinin sebebidir. in spite of zıtlık kurar, in case of ise “olması hâlinde” anlamıyla koşul bildirir."},
  {id:"r-con-cause-05", sub:"con-cause", from:["w2-12"], q:"---- most of the population lives near the coast, rising sea levels pose a serious threat to the country's economy.", o:["Even though","Unless","Whereas","As if","Given that"], a:4, e:"Given that = -dığı göz önüne alındığında (sebep); nüfusun kıyıda yaşaması tehdidin sebebidir. Even though zıtlık kurar, oysa iki bilgi birbiriyle çelişmez."},
  {id:"r-con-cause-06", sub:"con-cause", from:["w3-09","conj-05"], passage:"Tea became the national drink of Britain during the eighteenth century. At first it was an expensive luxury enjoyed mainly by the wealthy, and much of the tea sold in the country was smuggled in to avoid heavy taxes. Its consumption spread rapidly among all social classes, however, (1) ---- the government sharply reduced the tax on it in 1784, making legal tea affordable even for poor households. Within a few decades, tea drinking had become a central part of everyday British life.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["although","because","unless","whereas","so that"], a:1, e:"because + cümle = -dığı için; vergi indirimi çayın tüm sınıflara yayılmasının sebebidir. although zıtlık kurar, so that ise vergi indirimini yayılmanın amacı gibi gösterir."},
  {id:"r-con-cause-07", sub:"con-cause", from:["conj-06"], q:"The factory's output fell by 30 percent ---- a shortage of skilled workers.", o:["because","since","although","in spite of","owing to"], a:4, e:"owing to + isim öbeği = yüzünden; nitelikli işçi eksikliği üretimin düşmesinin sebebidir. because ve since ardından cümle ister; in spite of ise zıtlık bildirir."},
  {id:"r-con-cause-08", sub:"con-cause", from:["conj-06"], q:"---- the fact that the test results were inconclusive, the doctors ordered a second scan.", o:["Because","Although","Due to","Since","Despite"], a:2, e:"Due to the fact that + cümle = -dığı gerçeğinden dolayı. Because ve Since doğrudan “the fact” isim öbeğinin önüne gelemez; Despite ise belirsiz sonucu ikinci taramanın sebebi değil engeli gibi gösterir."},
  {id:"r-con-cause-09", sub:"con-cause", from:["conj-05","conj-07"], q:"Now that ----, residents no longer have to travel to the city for medical treatment.", o:["a fully equipped hospital has been built in the town","the nearest hospital is two hours away by car","many doctors prefer to work in large cities","the population of the town has been declining","public transport to the city is very limited"], a:0, e:"Now that = madem ki, artık … olduğuna göre; yeni ortaya çıkan sebep hastane yapılmasıdır. En yakın hastanenin uzak olması ya da ulaşımın kısıtlı olması şehre gitme zorunluluğunu kaldırmaz, tersine artırır."},
  {id:"r-con-cause-10", sub:"con-cause", from:["conj-05"], q:"Since ----, the government has decided to extend the programme to other regions.", o:["the pilot scheme failed to meet most of its targets","few people were aware of the programme","the programme was very expensive to run","the pilot scheme has proved highly successful","critics questioned the programme's effectiveness"], a:3, e:"Since burada “-dığı için” anlamındadır; programın başarılı olması yaygınlaştırılmasının sebebidir. Hedeflere ulaşamama, pahalılık veya eleştiriler programın genişletilmesine değil durdurulmasına gerekçe olur."},
  {id:"r-con-cause-11", sub:"con-cause", from:["w2-06"], q:"Many species of frog are disappearing, mainly ---- a fungal disease that has spread across several continents.", o:["on account of","because","as","in contrast to","regardless of"], a:0, e:"on account of + isim = yüzünden; mantar hastalığı kurbağaların yok olmasının sebebidir. because ve as ardından cümle ister; regardless of (-e bakmaksızın) ve in contrast to sebep bildirmez."},
  {id:"r-con-cause-12", sub:"con-cause", from:["conj-07"], q:"---- the museum is closed for renovation, the exhibition will be held at the city library.", o:["Although","Unless","As","So that","Despite"], a:2, e:"As + cümle = -dığı için; müzenin kapalı olması serginin kütüphanede yapılmasının sebebidir. Unless anlamı “müze kapalı olmadıkça” diye tersine çevirir, Despite ise cümle alamaz."},
  {id:"r-con-cause-13", sub:"con-cause", from:["conj-05","conj-07"], q:"The researchers chose to study identical twins ---- they share nearly all of their genes.", o:["because of","although","so that","because","unless"], a:3, e:"because + cümle = -dığı için; ikizlerin aynı genlere sahip olması seçilme sebebidir. because of ardından cümle alamaz; so that ise genlerin ortak olmasını araştırmacıların amacı gibi gösterir."},
  {id:"r-con-cause-14", sub:"con-cause", from:["w2-06"], q:"Air travel became accessible to ordinary people in the 1970s, largely ---- the introduction of larger aircraft and cheaper fares.", o:["in spite of","thanks to","instead of","because","in case of"], a:1, e:"thanks to + isim = sayesinde (olumlu sebep); büyük uçaklar ve ucuz biletler hava yolculuğunun yaygınlaşmasının sebebidir. because da sebep bildirir ama ardından isim öbeği değil cümle gerekir."},
  {id:"r-con-cause-15", sub:"con-cause", from:["conj-05"], q:"---- it rarely rains in the region, farmers rely almost entirely on irrigation.", o:["Even though","Due to","Unless","In spite of","Since"], a:4, e:"Since + cümle = -dığı için; yağışın az olması sulamaya bağımlılığın sebebidir. Due to ve In spite of ardından cümle alamaz; Even though ise mantıksız bir zıtlık kurar."},
  {id:"r-con-cause-16", sub:"con-cause", from:["conj-07","conj-06"], q:"The bridge was closed to heavy vehicles ---- engineers had discovered cracks in its supports.", o:["due to","despite","because","so that","although"], a:2, e:"because + cümle = -dığı için; çatlakların bulunması köprünün kapatılmasının sebebidir. due to da sebep bildirir ama ardından özne + yüklem (engineers had discovered) alamaz."},
  {id:"r-con-cause-17", sub:"con-cause", from:["conj-06","conj-07"], q:"---- the heavy rain, the match was postponed, ---- the pitch was completely flooded.", o:["Because of / as","Although / so","Despite / because","Due to / although","Since / unless"], a:0, e:"Birinci boşluktan sonra isim öbeği (the heavy rain) geldiği için Because of, ikinci boşluktan sonra cümle geldiği için as (-dığı için) gerekir. Due to / although ilk kısımda doğru olsa da although sebep yerine zıtlık kurar."},
  {id:"r-con-cause-18", sub:"con-cause", from:["w2-12"], q:"Given that ----, it is not surprising that sales of winter clothing fell sharply.", o:["temperatures dropped well below freezing for weeks","the winter was one of the mildest on record","prices of winter clothing were reduced considerably","the shops stayed open longer during the season","demand for warm coats usually rises in December"], a:1, e:"Given that sebep bildirir; kışın çok ılık geçmesi kışlık satışlarının düşmesini açıklar. Soğukların artması veya fiyat indirimi satışları düşürmez, artırır."},
  {id:"r-con-cause-19", sub:"con-cause", from:["conj-06"], q:"In view of ----, the committee postponed its final decision until next month.", o:["the data was not reliable","it lacked reliable data","because data was lacking","the lack of reliable data","although enough data was available"], a:3, e:"In view of (-i göz önünde bulundurarak) edattır ve ardından isim öbeği gelir: the lack of reliable data. Diğer seçenekler cümle ya da bağlaçla başladığı için edattan sonra kullanılamaz."},
  {id:"r-con-cause-20", sub:"con-cause", from:["w3-09","conj-06"], passage:"Honey is one of the few foods that almost never spoils. Archaeologists have found jars of honey in ancient Egyptian tombs that were still edible after thousands of years. This remarkable durability exists largely (1) ---- honey's low water content and high acidity, which together create an environment in which most bacteria and moulds cannot survive. Bees also add an enzyme that produces small amounts of hydrogen peroxide, which further protects the honey from contamination.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["because","in spite of","instead of","so that","because of"], a:4, e:"because of + isim öbeği (honey's low water content) = yüzünden, sayesinde. because ardından cümle ister; in spite of ise düşük nemi dayanıklılığın engeli gibi gösterir."},
  {id:"r-con-cause-21", sub:"con-cause", from:["conj-05"], q:"---- inflation remains high, the central bank is unlikely to cut interest rates in the near future.", o:["Although","Unless","Despite","Whereas","Because"], a:4, e:"Because + cümle = -dığı için; yüksek enflasyon faiz indirilmemesinin sebebidir. Although zıtlık kurar, Unless ise anlamı “enflasyon yüksek kalmadıkça” diye tersine çevirir."},
  {id:"r-con-cause-22", sub:"con-cause", from:["conj-06","w2-06"], q:"The flight was diverted to another airport ---- dense fog at its destination.", o:["as","because","even though","due to","so that"], a:3, e:"due to + isim öbeği (dense fog) = yüzünden. as ve because da sebep bildirir ama ardından özne + yüklem gerekir; so that ise amaç bildirir."},
  {id:"r-con-cause-23", sub:"con-cause", from:["conj-06","conj-07"], q:"---- being located far from major trade routes, the village remained isolated for centuries.", o:["Because","Because of","As","Although","Despite"], a:1, e:"Because of + V-ing (being located) = -dığı için; ticaret yollarından uzak olmak köyün yalnız kalmasının sebebidir. Because ve As ardından V-ing değil cümle alır; Although ve Despite ise zıtlık kurar."},
  {id:"r-con-cause-24", sub:"con-cause", from:["conj-05"], q:"Some scientists doubt the results of the study ---- the sample used in it was very small.", o:["since","despite","although","due to","so that"], a:0, e:"since + cümle = -dığı için; örneklemin küçük olması sonuçlardan şüphe etmenin sebebidir. although zıtlık kurar; due to ise ardından cümle alamaz."},
  {id:"r-con-cause-25", sub:"con-cause", from:["conj-06"], q:"---- a lack of funding, the research project had to be abandoned after only two years.", o:["As","Since","Owing to","Despite","Because"], a:2, e:"Owing to + isim öbeği (a lack of funding) = yüzünden. As, Since ve Because da sebep bildirir ama ardından cümle ister; Despite ise zıtlık kurar."},
  {id:"r-con-cause-26", sub:"con-cause", from:["conj-07"], q:"As ----, the company has been forced to raise its prices.", o:["the company's sales have risen steadily","customers have complained about higher prices","competitors have lowered their prices","the cost of raw materials has increased considerably","the company was founded more than a century ago"], a:3, e:"As “-dığı için” anlamındadır; hammadde maliyetinin artması şirketi fiyat artırmaya zorlar. Rakiplerin fiyat düşürmesi ise fiyat artırmaya zorlayan değil engelleyen bir etkendir."},
  {id:"r-con-cause-27", sub:"con-cause", from:["w3-09","conj-06"], passage:"The Dust Bowl of the 1930s was one of the worst environmental disasters in American history. Huge clouds of dust swept across the southern Great Plains, destroying crops and forcing thousands of families to abandon their farms. The storms occurred partly (1) ---- a severe drought that lasted for most of the decade, but farming practices also played a major role. Settlers had ploughed up the deep-rooted native grasses that had previously held the soil in place, leaving it exposed to the wind.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["because","due to","although","in spite of","so that"], a:1, e:"due to + isim öbeği (a severe drought) = yüzünden; kuraklık toz fırtınalarının sebeplerinden biridir. because ardından cümle ister; in spite of ise kuraklığı fırtınaların engeli gibi gösterir."},
  {id:"r-con-result-01", sub:"con-result", from:["conj-08"], q:"The lecture was ---- boring ---- several students fell asleep.", o:["such / that","too / to","enough / that","as / as","so / that"], a:4, e:"so + sıfat + that = o kadar … ki; boşluktan sonra yalnızca sıfat (boring) var. such isim öbeğiyle kullanılır (such a boring lecture that)."},
  {id:"r-con-result-02", sub:"con-result", from:["conj-09"], q:"It was ---- an unusual discovery ---- scientists spent years trying to explain it.", o:["so / that","too / to","such / that","as / as","enough / to"], a:2, e:"such + a/an + sıfat + isim + that = öyle … ki. so doğrudan “an unusual discovery” gibi a/an ile başlayan bir isim öbeğinden önce gelemez."},
  {id:"r-con-result-03", sub:"con-result", from:["conj-08"], q:"There were ---- many applicants for the job ---- the company had to hold interviews over three weeks.", o:["such / that","so / that","too / to","very / that","enough / as"], a:1, e:"so many/much/few/little + isim + that kalıbında such değil so kullanılır. very sonuç cümlesi (that) başlatamaz; too / to ise ardından cümle değil mastar ister."},
  {id:"r-con-result-04", sub:"con-result", from:["conj-10","w2-07"], q:"The factory has installed new filters; ----, the amount of pollution it releases has fallen by half.", o:["however","nevertheless","in contrast","as a result","otherwise"], a:3, e:"as a result = sonuç olarak; filtreler kirliliğin azalmasının sebebidir. however/nevertheless beklenmedik bir durum bildirir, otherwise ise “aksi hâlde” anlamıyla uymaz."},
  {id:"r-con-result-05", sub:"con-result", from:["w2-07"], q:"Heavy rains destroyed much of the harvest; ----, food prices rose sharply across the region.", o:["consequently","nonetheless","on the other hand","likewise","even so"], a:0, e:"consequently = dolayısıyla; hasadın yok olması fiyat artışının doğal sonucudur. nonetheless ve even so beklentiye aykırı bir durum bildirir, oysa sonuç tamamen beklenen yöndedir."},
  {id:"r-con-result-06", sub:"con-result", from:["conj-11"], q:"The new battery can be fully charged in just ten minutes, ---- reducing one of the main disadvantages of electric cars.", o:["whereas","although","thereby","because","unless"], a:2, e:"thereby + V-ing = böylece, bu sayede; hızlı şarj bir dezavantajı azaltır. because ardından V-ing değil cümle alır ve sebep bildirir; whereas ise karşılaştırma yapar."},
  {id:"r-con-result-07", sub:"con-result", from:["conj-11"], q:"The leaves of these trees stay green throughout the winter, ---- the name \"evergreen\".", o:["hence","whereas","because","although","despite"], a:0, e:"hence + isim = bu yüzden, adı da buradan gelir (hence the name). because ardından cümle ister; despite ise yaprakların yeşil kalmasını isme engel gibi gösterir."},
  {id:"r-con-result-08", sub:"con-result", from:["conj-09"], q:"The instructions were written in ---- technical language ---- most users could not understand them.", o:["so / that","too / to","such a / that","such / that","so much / as"], a:3, e:"such + sıfat + isim + that; “language” burada sayılamaz olduğu için a kullanılmaz. so bir isim öbeğinden (technical language) önce gelemez."},
  {id:"r-con-result-09", sub:"con-result", from:["conj-08"], q:"The medicine is ---- strong ---- be given to young children.", o:["so / that","too / to","such / that","enough / to","as / as"], a:1, e:"too + sıfat + to V1 = … -emeyecek kadar; ilaç çocuklara verilemeyecek kadar güçlü. enough sıfattan sonra gelir (strong enough to), so / that ise ardından özne gerektirir (so strong that it cannot)."},
  {id:"r-con-result-10", sub:"con-result", from:["conj-09","conj-08"], q:"The volcano erupted with ---- force ---- ash was carried hundreds of kilometres.", o:["so / that","too / to","so much / as","as / that","such / that"], a:4, e:"such + sayılamaz isim + that = öyle … ki (such force that). so doğrudan isimden (force) önce gelemez; so much / as ise yanlış eşleşmedir (so much … that olmalı)."},
  {id:"r-con-result-11", sub:"con-result", from:["conj-10"], q:"The company failed to adapt to digital technology; ----, it lost most of its customers to online competitors.", o:["however","therefore","otherwise","whereas","in contrast"], a:1, e:"therefore = bu yüzden; dijitale uyum sağlayamamak müşteri kaybının sebebidir. however ve in contrast zıtlık kurar; whereas ise noktalı virgülden sonra geçiş zarfı olarak kullanılamaz."},
  {id:"r-con-result-12", sub:"con-result", from:["conj-11"], q:"Sea ice in the Arctic is melting faster than scientists predicted, ---- threatening the survival of polar bears and other species that depend on it.", o:["although","whereas","because","thus","unless"], a:3, e:"thus + V-ing = böylece, dolayısıyla; buzların erimesinin sonucu verilir. because ardından V-ing değil cümle alır ve sonucu sebep gibi gösterir."},
  {id:"r-con-result-13", sub:"con-result", from:["conj-08"], q:"The new drug was so effective in early trials that ----.", o:["few doctors were willing to prescribe it","the trials had to be stopped because of serious side effects","researchers doubted it would ever be approved","it was quickly withdrawn from the market","regulators agreed to speed up its approval process"], a:4, e:"so … that sonuç bildirir; ilacın çok etkili olması onay sürecinin hızlandırılmasının doğal sonucudur. Diğer seçenekler (reçete yazılmaması, piyasadan çekilme) etkinliğin sonucu değil tersidir."},
  {id:"r-con-result-14", sub:"con-result", from:["conj-10","w2-07"], q:"The city lowered speed limits on all residential streets; as a result, ----.", o:["the city had been planning the change for several years","the decision was criticised by some motorists' groups before it was made","the number of serious road accidents fell by nearly 40 percent","traffic lights had already been installed at several junctions","accidents on motorways were not affected by the old limits"], a:2, e:"as a result, önceki eylemin sonucunu ister; hız sınırlarının düşürülmesinin sonucu kazaların azalmasıdır. Diğer seçenekler karardan önceki durumları veya ilgisiz bilgileri verir."},
  {id:"r-con-result-15", sub:"con-result", from:["conj-10"], q:"Few people could afford the new treatment; ----, it was rarely used outside large private hospitals.", o:["accordingly","nevertheless","by contrast","however","even so"], a:0, e:"accordingly = buna bağlı olarak, dolayısıyla; tedavinin pahalı olması az kullanılmasının sebebidir. nevertheless, however ve even so zıtlık bildirir, burada zıtlık yoktur."},
  {id:"r-con-result-16", sub:"con-result", from:["conj-10"], q:"The city is built on a major fault line, ---- it experiences frequent earthquakes.", o:["yet","although","whereas","so","unless"], a:3, e:"so = bu yüzden; fay hattı üzerinde olmak sık depremin sebebidir. yet ve although zıtlık kurar, oysa sonuç beklenen yöndedir."},
  {id:"r-con-result-17", sub:"con-result", from:["conj-08"], q:"There was ---- little rainfall last spring ---- the reservoir fell to its lowest level in fifty years.", o:["such / that","so / that","too / that","very / as","such a / that"], a:1, e:"so + little/much/few/many + isim + that kalıbında so kullanılır (so little rainfall that). such little ve such a little bu kalıpta kullanılmaz; too / that yanlış eşleşmedir."},
  {id:"r-con-result-18", sub:"con-result", from:["conj-10"], q:"The region has very few paved roads; ----, many villages can only be reached by boat.", o:["in contrast","nevertheless","for this reason","on the contrary","instead"], a:2, e:"for this reason = bu nedenle; yolların azlığı köylere tekneyle ulaşılmasının sebebidir. nevertheless ve in contrast zıtlık bildirir; on the contrary ise önceki cümleyi reddeder."},
  {id:"r-con-result-19", sub:"con-result", from:["conj-10","w2-07"], passage:"Bees pollinate around one third of the crops that humans eat, including many fruits, nuts and vegetables. In recent decades, however, bee populations have fallen sharply in many parts of the world because of pesticides, disease and habitat loss. Farmers in some regions have seen their harvests shrink, and (1) ----, the prices of fruits such as almonds and apples have risen considerably. Scientists warn that further declines could threaten global food security.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["nevertheless","in contrast","on the other hand","for instance","as a result"], a:4, e:"as a result = sonuç olarak; hasatların küçülmesinin sonucu fiyatların artmasıdır. nevertheless ve on the other hand zıtlık kurar, oysa fiyat artışı beklenen sonuçtur."},
  {id:"r-con-result-20", sub:"con-result", from:["conj-11"], passage:"The Great Fire of London in 1666 destroyed more than 13,000 houses and nearly ninety churches. Most buildings at the time were made of wood and packed closely together along narrow streets, (1) ---- allowing the flames to spread rapidly from one district to the next. After the fire, new regulations required buildings to be constructed of brick and stone, and streets were made wider to reduce the risk of similar disasters in the future.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["thus","although","whereas","because","despite"], a:0, e:"thus + V-ing = böylece; ahşap ve bitişik binalar yangının yayılmasının sebebidir. because ve although ardından V-ing değil cümle alır; despite ise anlamı zıtlığa çevirir."},
  {id:"r-con-result-21", sub:"con-result", from:["conj-08"], q:"The results of the study were ---- surprising that the researchers repeated the experiment three times.", o:["so","such","too","very","enough"], a:0, e:"so + sıfat + that = o kadar … ki. such isim öbeğiyle kullanılır; too ve enough to + V1 ister, very ise that ile sonuç cümlesi kuramaz."},
  {id:"r-con-result-22", sub:"con-result", from:["conj-09"], q:"It was ---- successful campaign that the government decided to repeat it the following year.", o:["so","too","so much","such","such a"], a:4, e:"such + a + sıfat + tekil sayılabilir isim + that; “campaign” sayılabilir ve tekil olduğu için a gerekir. so bir isim öbeğinin önüne gelemez, such ise tek başına a olmadan tekil isimle kullanılamaz."},
  {id:"r-con-result-23", sub:"con-result", from:["conj-10"], q:"The river is heavily polluted by industrial waste; ----, swimming and fishing have been banned along most of its length.", o:["otherwise","whereas","therefore","although","nonetheless"], a:2, e:"therefore = bu yüzden; kirlilik yasağın sebebidir. nonetheless zıtlık bildirir; whereas ve although ise noktalı virgül ve virgül arasında geçiş zarfı olarak kullanılamaz."},
  {id:"r-con-result-24", sub:"con-result", from:["conj-10","conj-11"], q:"Copper is an excellent conductor of electricity; ----, it is widely used in electrical wiring.", o:["however","thus","instead","on the other hand","in contrast"], a:1, e:"thus = bu nedenle; iyi iletken olması kablolarda kullanılmasının sebebidir. however, on the other hand ve in contrast zıtlık bildirir, burada zıtlık yoktur."},
  {id:"r-con-result-25", sub:"con-result", from:["conj-11"], q:"Tourism in the region grew rapidly during the 1990s, thus ----.", o:["because many visitors came from abroad","although the local government had opposed it","it created thousands of new jobs","creating thousands of new jobs in hotels and restaurants","which surprised many local officials"], a:3, e:"Virgülden sonra gelen thus ardından V-ing alarak sonucu verir: creating thousands of new jobs. “it created …” anlamca doğru olsa da thus'tan sonra virgülle bağlı özne + yüklem gelemez."},
  {id:"r-con-result-26", sub:"con-result", from:["conj-08"], q:"The mountain road was ---- narrow ---- two cars to pass each other.", o:["so / that","such / that","enough / for","very / so","too / for"], a:4, e:"too + sıfat + for + isim + to V1 = … -emeyecek kadar (iki arabanın geçemeyeceği kadar dar). so / that ardından “to pass” gibi mastar değil özne + yüklem ister; enough ise sıfattan sonra gelir."},
  {id:"r-con-result-27", sub:"con-result", from:["w2-07"], q:"The company's new phone had a serious battery fault; ----, millions of units had to be recalled.", o:["in spite of this","on the contrary","as a consequence","by contrast","in the same way"], a:2, e:"as a consequence = sonuç olarak; batarya arızası telefonların geri çağrılmasının sebebidir. in spite of this beklentiye aykırı bir durum bildirir, oysa geri çağırma beklenen sonuçtur."},
  {id:"r-con-purpose-01", sub:"con-purpose", from:["conj-12"], q:"Scientists froze the samples immediately ---- preserve their original chemical structure.", o:["so as to","so that","in case","because","provided that"], a:0, e:"so as to + V1 = -mek için; boşluktan sonra yalın fiil (preserve) geliyor. so that de amaç bildirir ama ardından özne + yüklem gerekir (so that they could preserve)."},
  {id:"r-con-purpose-02", sub:"con-purpose", from:["conj-13"], q:"The speaker used a microphone ---- everyone in the large hall could hear her clearly.", o:["in order to","so as to","due to","so that","in spite of"], a:3, e:"so that + özne + could = -sin diye. in order to ve so as to da amaç bildirir ama ardından cümle değil yalın fiil gelir."},
  {id:"r-con-purpose-03", sub:"con-purpose", from:["conj-14"], q:"Hikers are advised to carry extra water ---- they become dehydrated in the heat.", o:["so that","in order that","lest","unless","provided that"], a:2, e:"lest + özne + (should) V1 = -mesin diye; susuz kalmamaları için su taşıyorlar. so that ve in order that de amaç bildirir ama burada susuz kalmanın istendiği anlamı çıkar."},
  {id:"r-con-purpose-04", sub:"con-purpose", from:["conj-12"], q:"The government is investing in public transport ---- reduce traffic congestion in major cities.", o:["so that","in case","because of","as long as","in order to"], a:4, e:"in order to + V1 = -mek için; ardından yalın fiil (reduce) gelir. so that de amaç bildirir ama ardından özne + yüklem gerekir."},
  {id:"r-con-purpose-05", sub:"con-purpose", from:["conj-12"], q:"Doctors recommend washing hands frequently ---- not to spread infections.", o:["so that","so as","lest","for fear","so"], a:1, e:"so as not to + V1 = -memek için; olumsuz amaçta not, to'dan önce gelir. lest zaten olumsuz anlamlıdır ve ardından cümle ister; so that de cümle gerektirir."},
  {id:"r-con-purpose-06", sub:"con-purpose", from:["conj-13"], q:"The museum lowered its entrance fees ---- more families could afford to visit.", o:["in order to","so as to","due to","in order that","despite"], a:3, e:"in order that + özne + could = -sin diye (so that ile aynı). in order to ve so as to ardından özne + yüklem (more families could afford) alamaz."},
  {id:"r-con-purpose-07", sub:"con-purpose", from:["w4-07"], q:"So that local residents can take part in the decision-making process, ----.", o:["the council had approved the plan without consulting anyone","the council will hold a series of public meetings next month","many residents were unaware of the plan","few people attended the previous meeting","the plan was opposed by several local businesses"], a:1, e:"So that amaç bildirir; halk toplantıları sakinlerin karara katılması amacına hizmet eder. Planın kimseye danışılmadan onaylanması ya da sakinlerin plandan habersiz olması amaçla çelişir."},
  {id:"r-con-purpose-08", sub:"con-purpose", from:["conj-14"], q:"Many people avoid visiting the doctor ---- receiving bad news.", o:["so that","in order to","lest","in case","for fear of"], a:4, e:"for fear of + V-ing = … korkusuyla; ardından V-ing (receiving) geliyor. lest ve so that ardından cümle, in order to ise yalın fiil ister."},
  {id:"r-con-purpose-09", sub:"con-purpose", from:["conj-13","w2-08"], q:"Engineers reinforced the old bridge ---- it could carry heavier traffic.", o:["in order to","so as to","so that","because of","although"], a:2, e:"so that + özne + could = -sin diye; güçlendirmenin amacı ağır trafiği taşıyabilmektir. in order to ve so as to ardından özne (it) alamaz, yalın fiil ister."},
  {id:"r-con-purpose-10", sub:"con-purpose", from:["conj-12"], q:"The rules were written in plain language ---- avoid any misunderstanding.", o:["so as to","in order that","so that","lest","for fear that"], a:0, e:"so as to + V1 = -mek için; ardından yalın fiil (avoid) gelir. in order that, so that, lest ve for fear that ise özne + yüklem içeren bir cümle ister."},
  {id:"r-con-purpose-11", sub:"con-purpose", from:["conj-14"], q:"Some animals remain completely still ---- they should attract the attention of predators.", o:["so that","in order to","lest","now that","as long as"], a:2, e:"lest + özne + should + V1 = -mesin diye; hayvanlar avcıların dikkatini çekmemek için hareketsiz kalır. so that burada dikkat çekmenin amaçlandığı anlamını verir; in order to ise ardından cümle alamaz."},
  {id:"r-con-purpose-12", sub:"con-purpose", from:["conj-12","w4-07"], q:"In order to reduce the risk of heart disease, ----.", o:["the number of heart attacks has risen in recent years","many people have a family history of heart problems","heart disease was once considered a disease of the rich","smoking increases blood pressure significantly","people are advised to exercise regularly and eat less salt"], a:4, e:"In order to amaç bildirir; ana cümle bu amaca yönelik bir eylem içermelidir: egzersiz ve az tuz önerisi. Kalp krizlerinin artması veya aile geçmişi bir amaca hizmet eden eylem değil durum bildirir."},
  {id:"r-con-purpose-13", sub:"con-purpose", from:["conj-12"], q:"The researchers did not reveal the names of the participants ---- protect their privacy.", o:["in order to","so that","in order that","lest","for fear"], a:0, e:"in order to + V1 = -mek için; ardından yalın fiil (protect) gelir. so that ve in order that cümle ister; lest ise olumsuz amaç bildirir ve özne gerektirir."},
  {id:"r-con-purpose-14", sub:"con-purpose", from:["w2-08","conj-13"], q:"The company translated its website into six languages ---- it could reach customers around the world.", o:["in order to","so as to","lest","so that","because of"], a:3, e:"so that + özne + could = -sin diye. lest “-mesin diye” anlamıyla müşterilere ulaşılmamasını amaçlar; in order to ve so as to ise ardından özne alamaz."},
  {id:"r-con-purpose-15", sub:"con-purpose", from:["conj-14","conj-13"], q:"Farmers rotate their crops ---- the soil does not lose its nutrients.", o:["lest","so that","so as to","in order to","for fear of"], a:1, e:"so that + olumsuz cümle = -mesin diye (the soil does not lose). lest zaten olumsuz anlamlı olduğu için ardından not gelmez; so as to ve in order to ise cümle alamaz."},
  {id:"r-con-purpose-16", sub:"con-purpose", from:["conj-14"], q:"The windows of the laboratory were kept closed ---- dust should get in and contaminate the samples.", o:["in order that","so that","so as to","unless","lest"], a:4, e:"lest + özne + should = -mesin diye; pencereler toz girmesin diye kapalı tutuldu. so that ve in order that tozun girmesinin istendiği anlamını verir; so as to ise ardından cümle alamaz."},
  {id:"r-con-purpose-17", sub:"con-purpose", from:["w2-08","conj-13"], passage:"In the eighteenth century, sailors on long voyages often suffered from scurvy, a disease caused by a lack of vitamin C. Thousands died from it, and some ships lost more men to scurvy than to battle. After the Scottish doctor James Lind showed that citrus fruits could cure the illness, the British navy eventually began giving its sailors lemon juice every day (1) ---- they would stay healthy during months at sea. As a result, scurvy almost disappeared from the fleet.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["in order to","so as to","so that","despite","in case of"], a:2, e:"so that + özne + would = -sin diye; limon suyu denizcilerin sağlıklı kalması amacıyla veriliyordu. in order to ve so as to ardından özne + yüklem (they would stay) alamaz."},
  {id:"r-con-purpose-18", sub:"con-purpose", from:["conj-12"], passage:"Many cities are planting more trees along their streets. Trees provide shade and release moisture into the air, which helps to lower temperatures during summer heatwaves. They also absorb rainwater and reduce the risk of flooding. However, city planners must choose species carefully (1) ---- avoid damage to pavements and underground pipes, since some trees have very aggressive roots that can break through concrete.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["so that","in case","because","in order to","as long as"], a:3, e:"in order to + V1 = -mek için; ardından yalın fiil (avoid) geliyor. so that de amaç bildirir ama ardından özne + yüklem gerekir; because ise sebep bildirir ve cümle ister."},
  {id:"r-con-purpose-19", sub:"con-purpose", from:["conj-12"], q:"The government introduced a sugar tax ---- encourage manufacturers to reduce the sugar content of soft drinks.", o:["so as to","so that","lest","for fear of","with the aim of"], a:0, e:"so as to + V1 = -mek için. with the aim of da amaç bildirir ama ardından V-ing gerekir (with the aim of encouraging); so that ve lest ise cümle ister."},
  {id:"r-con-purpose-20", sub:"con-purpose", from:["conj-13"], q:"The organisers set up extra first-aid tents ---- anyone who felt unwell could be treated quickly.", o:["so as to","in order that","in order to","for fear of","owing to"], a:1, e:"in order that + özne + could = -sin diye. so as to ve in order to ardından yalın fiil ister, for fear of ve owing to ise isim/V-ing alır; hiçbiri cümle alamaz."},
  {id:"r-con-purpose-21", sub:"con-purpose", from:["conj-13"], q:"The ancient Egyptians preserved the bodies of the dead ---- the soul would be able to recognise and return to them.", o:["in order to","so that","so as to","lest","because of"], a:1, e:"so that + özne + would = -sin diye; mumyalamanın amacı ruhun bedeni tanıyabilmesidir. lest bunun olmamasını amaçlar ve anlamı tersine çevirir."},
  {id:"r-con-purpose-22", sub:"con-purpose", from:["conj-14"], q:"The data were stored on two separate servers lest ----.", o:["one of them should fail","both of them could work properly","one of them should not fail","the system is much faster","they had been damaged before"], a:0, e:"lest + özne + should + V1 = -mesin diye; sunuculardan biri çökmesin diye veriler iki yerde tutulur. lest zaten olumsuz anlam taşıdığı için ardından not kullanılmaz (should not fail yanlıştır)."},
  {id:"r-con-purpose-23", sub:"con-purpose", from:["conj-14"], q:"Students are encouraged to take notes during lectures ---- they forget the key points.", o:["so that","in order to","as though","lest","even though"], a:3, e:"lest + özne + V1 = -mesin diye; not almak önemli noktaları unutmamak içindir. so that burada unutmanın amaçlandığı anlamını verir; in order to ise ardından cümle alamaz."},
  {id:"r-con-purpose-24", sub:"con-purpose", from:["conj-12","conj-13"], q:"The doctor prescribed a lower dose ---- the risk of side effects.", o:["so that reducing","in order that reduce","so as to reduce","lest reduce","for fear of reduce"], a:2, e:"so as to + V1 = -mek için (so as to reduce). so that ve in order that ardından özne + yüklem ister; for fear of V-ing, lest ise cümle alır."},
  {id:"r-con-purpose-25", sub:"con-purpose", from:["conj-13","w2-08"], q:"Many parents limit their children's screen time ---- they will spend more time playing outdoors.", o:["in order to","so as to","for fear of","in spite of","so that"], a:4, e:"so that + özne + will = -sin diye; ekran süresini kısıtlamanın amacı çocukların dışarıda daha çok oynamasıdır. in order to ve so as to ardından özne alamaz; for fear of ise V-ing ister ve anlamı tersine çevirir."},
  {id:"r-con-purpose-26", sub:"con-purpose", from:["conj-13","conj-14"], q:"The bank sends customers a security code by text message ---- unauthorised people cannot access their accounts.", o:["so that","in order to","so as not to","lest","for fear of"], a:0, e:"so that + olumsuz cümle = -mesin diye (unauthorised people cannot access). lest ardından not/cannot almaz çünkü kendisi olumsuzdur; so as not to ve in order to ise cümle alamaz."},
  {id:"r-con-purpose-27", sub:"con-purpose", from:["conj-13","w2-08"], passage:"Before an important exam, many students stay up late revising. Sleep researchers warn that this habit can be counterproductive, because the brain consolidates newly learned information during deep sleep. Students who sleep well tend to remember more and perform better than those who study all night. Researchers therefore recommend that students plan their revision carefully (1) ---- they can get at least seven hours of sleep the night before the test.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["in order to","lest","so as to","so that","due to"], a:3, e:"so that + özne + can = -sin diye; planlı çalışmanın amacı yeterli uyuyabilmektir. lest anlamı “uyuyamasınlar diye” şeklinde tersine çevirir; in order to ve so as to cümle alamaz."},
  {id:"r-con-correlative-01", sub:"con-correlative", from:["conj-15","w2-09"], q:"---- the manager ---- her assistants were aware of the error until the auditors pointed it out.", o:["Both / and","Neither / nor","Either / nor","Not only / but also","Whether / or"], a:1, e:"Neither … nor = ne … ne de; “until the auditors pointed it out” hatanın kimse tarafından bilinmediğini gösterir. Both / and ve Not only / but also anlamı tersine çevirir; Either / nor yanlış eşleşmedir."},
  {id:"r-con-correlative-02", sub:"con-correlative", from:["conj-16"], q:"According to the results of three large trials, the new vaccine is ---- safe ---- effective.", o:["either / nor","neither / or","not only / as well","whether / nor","both / and"], a:4, e:"both … and = hem … hem de; iki olumlu özellik birlikte veriliyor. either / nor, neither / or, not only / as well ve whether / nor yanlış eşleşmelerdir."},
  {id:"r-con-correlative-03", sub:"con-correlative", from:["conj-15"], q:"Visitors can pay ---- in cash ---- by credit card at the museum entrance.", o:["neither / or","both / nor","not only / or","either / or","whether / nor"], a:3, e:"either … or = ya … ya da; ziyaretçiye iki ödeme seçeneği sunuluyor. Diğer seçenekler yanlış eşleşmelerdir (neither nor ile, both and ile eşleşir)."},
  {id:"r-con-correlative-04", sub:"con-correlative", from:["conj-17"], q:"The committee has not yet decided ---- to approve the proposal ---- to reject it altogether.", o:["whether / or","either / nor","both / and","neither / or","not only / but"], a:0, e:"whether … or = … mı yoksa … mı; “has not yet decided” belirsizlik bildirir. both / and iki kararın birlikte alınmasını gerektirir, çelişkilidir; either / nor ve neither / or yanlış eşleşmedir."},
  {id:"r-con-correlative-05", sub:"con-correlative", from:["conj-16"], q:"The festival ---- attracts thousands of tourists ---- provides valuable income for local businesses.", o:["either / nor","neither / or","not only / but also","whether / or","both / nor"], a:2, e:"not only … but also = yalnızca … değil, aynı zamanda; iki olumlu etki paralel fiillerle sıralanıyor. whether / or belirsizlik bildirir; diğerleri yanlış eşleşmedir."},
  {id:"r-con-correlative-06", sub:"con-correlative", from:["conj-15"], q:"---- the students ---- the teacher has access to the exam questions before the day of the test.", o:["Both / and","Whether / or","Such / that","Either / nor","Neither / nor"], a:4, e:"Neither … nor ile fiil yakındaki özneye (the teacher) uyar ve tekil olur (has). Both / and çoğul fiil ister (have); Either / nor ise yanlış eşleşmedir."},
  {id:"r-con-correlative-07", sub:"con-correlative", from:["conj-17"], q:"Researchers are trying to determine ---- the newly discovered species is venomous ---- not.", o:["either / nor","neither / or","whether / or","both / and","so / as"], a:2, e:"whether … or not = … olup olmadığı; “trying to determine” belirsizlik bildirir. either / nor ve neither / or yanlış eşleşmedir; both / and ise “or not” ile anlamsızlaşır."},
  {id:"r-con-correlative-08", sub:"con-correlative", from:["w2-09","conj-15"], q:"In the early nineteenth century, ---- women ---- men without property were allowed to vote in most countries, so universal suffrage was the result of a long struggle.", o:["neither / nor","both / and","either / or","not only / but also","whether / or"], a:0, e:"Neither … nor = ne … ne de; genel oy hakkının uzun bir mücadeleyle kazanılması bu grupların oy kullanamadığını gösterir. Both / and ve Not only / but also anlamı tersine çevirir."},
  {id:"r-con-correlative-09", sub:"con-correlative", from:["conj-16"], q:"The disease affects ---- adults ---- children, although it is usually more severe in older patients.", o:["neither / or","either / nor","whether / nor","both / and","not only / and"], a:3, e:"both … and = hem … hem de; hastalık iki grubu da etkiler, although yalnızca şiddet farkını belirtir. Diğer seçenekler yanlış eşleşmelerdir (not only but also ile eşleşir)."},
  {id:"r-con-correlative-10", sub:"con-correlative", from:["conj-15"], q:"You can ---- renew your passport online ---- apply in person at the consulate; both options take about two weeks.", o:["neither / nor","either / or","both / or","not only / nor","whether / and"], a:1, e:"either … or = ya … ya da; “both options” iki seçenek olduğunu gösterir. neither / nor iki yolun da mümkün olmadığı anlamını verir ve cümlenin devamıyla çelişir."},
  {id:"r-con-correlative-11", sub:"con-correlative", from:["conj-16"], q:"The report was criticised not only for its inaccurate data ----.", o:["nor for its poorly supported conclusions","or for its poorly supported conclusions","but also its conclusions were poorly supported","but also for its poorly supported conclusions","and for which the conclusions were poor"], a:3, e:"not only … but also eşlenir ve bağlanan öğeler paralel olmalıdır: for its data – for its conclusions. “but also its conclusions were …” eşleşme doğru olsa da paralel yapıyı bozar."},
  {id:"r-con-correlative-12", sub:"con-correlative", from:["conj-16"], q:"---- does the new law protect consumers, but it also encourages competition between companies.", o:["Not only","Neither","Either","Both","Whether"], a:0, e:"Not only cümle başında gelince devrik yapı (does the new law protect) gerektirir ve “but … also” ile eşleşir. Neither de devrik yapı alır ama nor ile eşleşir; Both ve Either devrik yapı kurmaz."},
  {id:"r-con-correlative-13", sub:"con-correlative", from:["conj-16"], q:"The explorer's diary is ---- a scientific record ---- a personal memoir, combining detailed observations with private reflections.", o:["neither / nor","both / and","either / nor","whether / or","not only / nor"], a:1, e:"both … and = hem … hem de; “combining” günlüğün iki niteliği birlikte taşıdığını gösterir. neither / nor iki niteliği de reddeder ve “combining” ile çelişir."},
  {id:"r-con-correlative-14", sub:"con-correlative", from:["conj-15"], q:"Neither the patients nor the doctor ---- informed about the change in the treatment plan.", o:["were","have been","are","being","was"], a:4, e:"Neither … nor yapısında fiil yakındaki özneye (the doctor) uyar, bu yüzden tekil was gelir. were ve have been uzaktaki çoğul özneye (patients) göre çekilmiştir."},
  {id:"r-con-correlative-15", sub:"con-correlative", from:["conj-15"], q:"Either the minister or her advisers ---- going to be asked to explain the decision to parliament.", o:["is","has","are","was","be"], a:2, e:"Either … or yapısında fiil yakındaki özneye (her advisers) uyar ve çoğul olur: are. is ve was uzaktaki tekil özneye (the minister) göre çekilmiştir."},
  {id:"r-con-correlative-16", sub:"con-correlative", from:["w2-09","conj-15"], q:"---- the island's economy ---- its ecosystem could survive another decade of uncontrolled tourism, experts warned, calling for immediate limits on visitor numbers.", o:["Neither / nor","Both / and","Either / nor","Whether / or","Not only / but also"], a:0, e:"Neither … nor = ne … ne de; uzmanların acil sınırlama istemesi ikisinin de dayanamayacağını gösterir. Both / and ve Not only / but also ikisinin de dayanabileceğini söyler, uyarıyla çelişir."},
  {id:"r-con-correlative-17", sub:"con-correlative", from:["conj-17"], q:"Whether the new plan succeeds ----.", o:["and fails will depend largely on public support","nor fails will depend largely on public support","but also fails will depend largely on public support","or fails will depend largely on public support","either fails will depend largely on public support"], a:3, e:"whether … or eşleşir: başarılı mı yoksa başarısız mı olacağı. and, nor ve but also whether ile eşleşmez."},
  {id:"r-con-correlative-18", sub:"con-correlative", from:["conj-16"], q:"Critics praised the film ---- for its acting ---- for its striking photography.", o:["neither / or","either / nor","whether / but","so / as","both / and"], a:4, e:"both … and = hem … hem de; film iki yönden övülüyor. Diğer seçenekler yanlış eşleşmedir (neither–nor, either–or)."},
  {id:"r-con-correlative-19", sub:"con-correlative", from:["conj-16"], passage:"Mangrove forests grow along tropical coastlines where land meets the sea. Although they cover only a small fraction of the world's forests, they are (1) ---- important for biodiversity but also valuable to humans. Their dense roots provide breeding grounds for many species of fish, and they protect coastal communities from storms and erosion. Unfortunately, large areas of mangroves have been cleared in recent decades to make way for shrimp farms and tourist resorts.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["neither","not only","either","both","whether"], a:1, e:"Boşluktan sonraki “but also” not only ile eşleşir: yalnızca biyolojik çeşitlilik için değil, insanlar için de değerli. both and ile, either or ile, neither nor ile eşleşir."},
  {id:"r-con-correlative-20", sub:"con-correlative", from:["conj-15","w2-09"], passage:"For centuries, sailors navigated the open sea using the stars and a few simple instruments. On cloudy nights, however, they could see (1) ---- the stars nor the moon, and ships frequently lost their way or ran aground. Calculating longitude was especially difficult. The invention of the marine chronometer in the eighteenth century finally allowed navigators to determine their position accurately, making long ocean voyages much safer.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["either","both","neither","not only","whether"], a:2, e:"Boşluktan sonraki nor, neither ile eşleşir: bulutlu gecelerde ne yıldızlar ne ay görülebiliyordu. either or ile, both and ile eşleşir; nor ile birlikte kullanılamaz."},
  {id:"r-con-correlative-21", sub:"con-correlative", from:["conj-17"], passage:"Before a new medicine can be sold to the public, it must pass through several stages of clinical testing. These trials are designed to show (1) ---- the drug is effective against the disease or not, and to identify any harmful side effects. Only a small proportion of the drugs that enter clinical trials are eventually approved, which is one reason why developing a new medicine can take more than ten years.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["either","neither","whether","both","not only"], a:2, e:"whether … or not = … olup olmadığı; denemeler ilacın etkili olup olmadığını gösterir. either de or ile eşleşir ama isim cümlesi (the drug is effective) başlatamaz."},
  {id:"r-con-correlative-22", sub:"con-correlative", from:["conj-15"], q:"Applicants must ---- hold a university degree ---- have at least five years of relevant experience; those who meet neither requirement will not be considered.", o:["neither / nor","either / or","both / nor","whether / and","not only / or"], a:1, e:"either … or = ya … ya da; “neither requirement” iki koşuldan birinin yeterli olduğunu gösterir. neither / nor iki koşulu da reddeder ve anlamı bozar; diğerleri yanlış eşleşmedir."},
  {id:"r-con-correlative-23", sub:"con-correlative", from:["conj-15"], q:"The treatment is ---- cheap ---- widely available, so most patients in rural areas cannot benefit from it.", o:["both / and","either / or","not only / but also","whether / or","neither / nor"], a:4, e:"neither … nor = ne … ne de; kırsaldaki hastaların yararlanamaması tedavinin ucuz da yaygın da olmadığını gösterir. both / and ve not only / but also bu sonuçla çelişir."},
  {id:"r-con-correlative-24", sub:"con-correlative", from:["conj-17"], q:"It makes little difference ---- the meeting is held on Monday ---- on Tuesday, as most staff will be available on both days.", o:["either / nor","both / and","neither / or","whether / or","not only / but"], a:3, e:"whether … or = … mı yoksa … mı (fark etmez); “It makes little difference” iki seçenek arasında kayıtsızlık bildirir. both / and toplantının iki gün birden yapılmasını anlatır, anlamsızdır."},
  {id:"r-con-correlative-25", sub:"con-correlative", from:["conj-16"], q:"The scientist was ---- a gifted researcher ---- an inspiring teacher, and many of her students went on to become leading experts.", o:["not only / but also","neither / nor","either / nor","whether / or","both / or"], a:0, e:"not only … but also = yalnızca … değil, aynı zamanda; öğrencilerinin başarısı onun iyi bir öğretmen olduğunu da gösterir. neither / nor bu olumlu sonuçla çelişir; diğerleri yanlış eşleşmedir."},
  {id:"r-con-correlative-26", sub:"con-correlative", from:["conj-15"], q:"---- the heat ---- the humidity makes the region pleasant in summer, which is why most residents leave for the mountains.", o:["Both / and","Neither / nor","Either / nor","Not only / but also","Whether / or"], a:1, e:"Neither … nor = ne … ne de; sakinlerin dağlara gitmesi bölgenin yazın hoş olmadığını gösterir ve fiil yakın özneye göre tekildir (makes). Both / and hem anlamı tersine çevirir hem de çoğul fiil ister."},
  {id:"r-con-correlative-27", sub:"con-correlative", from:["conj-17"], q:"The government must decide soon ---- to raise taxes ---- to cut public spending, since it cannot afford to do nothing.", o:["either / nor","neither / or","both / but","not only / and","whether / or"], a:4, e:"whether … or + to V1 = … mı yoksa … mı; hükümet iki seçenek arasında karar vermelidir. Diğer seçenekler yanlış eşleşmedir (either–or, neither–nor, both–and, not only–but also)."},
  {id:"r-con-time-01", sub:"con-time", from:["conj-18"], q:"---- the results of the survey are published, the committee will decide on the next steps.", o:["Although","Until","As soon as","Whereas","Unless"], a:2, e:"As soon as = -er -mez; sonuçlar yayımlanınca komite karar verecek (gelecek anlamlı zaman cümlesinde present simple). Until kararı sonuçlardan önceye yayar, Unless ise anlamı tersine çevirir."},
  {id:"r-con-time-02", sub:"con-time", from:["conj-19"], q:"---- the new airport opens, construction costs will have exceeded the original budget by 40 percent.", o:["By the time","Until","Now that","Unless","Whereas"], a:0, e:"By the time + present simple → ana cümlede future perfect (will have exceeded) = … olduğunda (çoktan). Until future perfect ile uyuşmaz; Now that ise havalimanının açılmış olduğunu varsayar."},
  {id:"r-con-time-03", sub:"con-time", from:["conj-19"], q:"---- the war ended in 1945, the city had been almost completely destroyed by bombing.", o:["Until","Now that","As soon as","Unless","By the time"], a:4, e:"By the time + past simple → ana cümlede past perfect (had been destroyed) = … olduğunda çoktan. As soon as savaş biter bitmez yıkıldığını söyler, zaman sırasını bozar."},
  {id:"r-con-time-04", sub:"con-time", from:["w2-10"], q:"The patient will remain under observation ---- her condition becomes stable.", o:["by the time","until","once","as soon as","now that"], a:1, e:"until = -e kadar; gözlem durum stabil hale gelene kadar sürer (süreklilik). once ve as soon as gözlemin stabil olduktan sonra başlayacağı anlamını verir, mantıksızdır."},
  {id:"r-con-time-05", sub:"con-time", from:["conj-20"], q:"---- smartphones have become widely available, people rarely use public telephones.", o:["Until","Before","By the time","Now that","Unless"], a:3, e:"Now that = artık … olduğuna göre; akıllı telefonların yaygınlaşması ankesörlü telefonların kullanılmamasının sebebidir. Until ve Before zaman sırasını tersine çevirir."},
  {id:"r-con-time-06", sub:"con-time", from:["w2-10"], q:"Many ancient manuscripts were lost ---- they could be copied or translated.", o:["before","after","once","now that","as soon as"], a:0, e:"before = -meden önce; el yazmaları kopyalanamadan kayboldu. after, once ve as soon as kopyalandıktan sonra kaybolduklarını söyler; “could be” ile uyuşmaz ve anlamı bozar."},
  {id:"r-con-time-07", sub:"con-time", from:["conj-18"], q:"---- the vaccine had been approved by the health authorities, it was distributed to hospitals across the country.", o:["Until","Before","By the time","Once","While"], a:3, e:"Once = -dikten sonra, -ince; aşı onaylanınca dağıtıldı. Before ve Until dağıtımı onaydan önceye koyar; While ise past perfect ile değil süregelen eylemle kullanılır."},
  {id:"r-con-time-08", sub:"con-time", from:["w2-10"], q:"Researchers did not realise how dangerous the chemical was ---- several workers became seriously ill.", o:["by the time","until","once","as soon as","while"], a:1, e:"not … until = -e kadar … -medi, ancak … olunca; tehlike işçiler hastalanınca fark edildi. once ve as soon as olumsuz ana cümleyle mantıksız bir anlam verir."},
  {id:"r-con-time-09", sub:"con-time", from:["conj-18"], q:"---- the technician was checking the equipment, the fire alarm suddenly went off.", o:["By the time","Until","Now that","Once","While"], a:4, e:"While + past continuous = -iken; kontrol sürerken alarm çaldı. By the time ana cümlede past perfect ister; Until ise sürekliliği bitiş noktasına bağlar ve “suddenly” ile uyuşmaz."},
  {id:"r-con-time-10", sub:"con-time", from:["conj-19"], q:"By the time the investigators reached the site, ----.", o:["most of the evidence will be removed","most of the evidence has been removed","most of the evidence had been removed","most of the evidence is being removed","most of the evidence would be removed as soon as they arrive"], a:2, e:"By the time + past simple (reached) ana cümlede past perfect ister: had been removed. has been removed present perfect olduğundan geçmişteki bir zaman noktasıyla uyuşmaz."},
  {id:"r-con-time-11", sub:"con-time", from:["conj-20"], q:"Now that ----, the museum can finally display its entire collection.", o:["the new exhibition wing will be completed next year","the building was too small for the collection","the museum had very limited storage space","construction of the new wing has been delayed","the new exhibition wing has been completed"], a:4, e:"Now that tamamlanmış yeni bir duruma dayanır; yeni kanadın bitmesi koleksiyonun sergilenmesini mümkün kılar. “will be completed” gelecekte olduğundan “can finally” ile uyuşmaz."},
  {id:"r-con-time-12", sub:"con-time", from:["conj-18"], q:"Once ---- the necessary permits, the company will start building the wind farm.", o:["it will receive","it receives","it would receive","it had received","it has been receiving"], a:1, e:"Gelecek anlamlı zaman cümlelerinde will kullanılmaz; once'tan sonra present simple (it receives) gelir. “it will receive” en sık yapılan hatadır."},
  {id:"r-con-time-13", sub:"con-time", from:["w2-10"], q:"The meeting cannot start ---- all board members have arrived.", o:["by the time","while","until","now that","as soon as"], a:2, e:"cannot … until = -meden başlayamaz, -e kadar başlayamaz. as soon as olumsuz ana cümleyle çelişir; now that ise üyelerin gelmiş olmasını toplantının başlayamama sebebi yapar."},
  {id:"r-con-time-14", sub:"con-time", from:["conj-18"], q:"---- the population of the city grew, the demand for clean water increased.", o:["As","Until","By the time","Although","Unless"], a:0, e:"As = -dikçe; nüfus arttıkça su talebi de arttı (paralel gelişen iki olay). Until ve By the time zaman ilişkisini bozar, Although ise olmayan bir zıtlık kurar."},
  {id:"r-con-time-15", sub:"con-time", from:["w2-10"], q:"---- the Internet became widely available, people relied mainly on libraries and printed encyclopedias for information.", o:["Now that","Once","As soon as","Before","After"], a:3, e:"Before = -meden önce; kütüphane ve ansiklopedilere dayanma internet yaygınlaşmadan önceki durumdur. After, Once ve As soon as bu durumu internetten sonraya koyar, zaman sırasını tersine çevirir."},
  {id:"r-con-time-16", sub:"con-time", from:["w2-10","conj-18"], q:"---- the storm passes, residents must stay indoors, and ---- it is safe, emergency teams will begin clearing the roads.", o:["Once / until","Until / once","By the time / until","Now that / before","While / unless"], a:1, e:"Fırtına geçene kadar içeride kalmak Until, güvenli olunca yolları temizlemeye başlamak once ile verilir. Once / until sırayı tersine çevirir: fırtına geçince içeride kalmak mantıksızdır."},
  {id:"r-con-time-17", sub:"con-time", from:["w2-10"], q:"It was not ---- the late nineteenth century that scientists understood how infectious diseases spread.", o:["by","since","before","once","until"], a:4, e:"It was not until … that = ancak … -de; bilim insanları bunu ancak 19. yüzyılın sonunda anladı. by ve before bu vurgu kalıbında kullanılmaz; since ise present perfect ister."},
  {id:"r-con-time-18", sub:"con-time", from:["conj-18"], q:"---- the speaker had finished her speech, the audience rose to their feet and applauded.", o:["As soon as","Until","Unless","While","Whereas"], a:0, e:"As soon as = -er -mez; konuşma biter bitmez dinleyiciler ayağa kalktı. Until alkışı konuşmadan önceye yayar, While ise past perfect ile değil süregelen eylemle kullanılır."},
  {id:"r-con-time-19", sub:"con-time", from:["conj-18"], q:"---- the heatwave continues, the risk of forest fires will remain extremely high.", o:["By the time","Until","As long as","Before","Unless"], a:2, e:"As long as = … sürdükçe; sıcak hava dalgası sürdükçe risk yüksek kalacak. Until ile “continues” birlikte anlamsızdır; Unless ise anlamı tersine çevirir."},
  {id:"r-con-time-20", sub:"con-time", from:["w2-10"], passage:"Penicillin was discovered by Alexander Fleming in 1928, but for more than a decade it remained little more than a laboratory curiosity because it was extremely difficult to produce. (1) ---- scientists developed methods of manufacturing it in large quantities during the Second World War, countless soldiers had died from infections in relatively minor wounds. Mass production transformed medicine and marked the beginning of the antibiotic era.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["Once","Now that","As soon as","Until","After"], a:3, e:"Until = -e kadar; ana cümledeki past perfect, askerlerin enfeksiyondan ölmesinin seri üretim başlayana kadar sürdüğünü gösterir. Once, As soon as ve After bu ölümleri seri üretimden sonraya koyar, anlamı bozar."},
  {id:"r-con-time-21", sub:"con-time", from:["conj-20"], passage:"Many city dwellers have started growing vegetables on balconies, rooftops and small shared plots. (1) ---- fresh produce can be grown so close to home, families spend less on groceries and tend to eat a healthier diet. Urban gardens also bring neighbours together and provide a habitat for bees and other pollinators. Some cities have even begun offering free seeds and training courses to encourage more residents to take up gardening.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["Until","Before","By the time","Now that","Unless"], a:3, e:"Now that = artık … olduğuna göre; ürünlerin evde yetiştirilebilmesi harcamaların azalmasının sebebidir. Until ve Before zaman sırasını tersine çevirir, Unless ise anlamı olumsuza döndürür."},
  {id:"r-con-time-22", sub:"con-time", from:["conj-19"], passage:"Construction of the Channel Tunnel between Britain and France began in 1988 and took six years to complete. The project was expected to take many passengers away from the ferry companies operating across the channel. (1) ---- the tunnel finally opened in 1994, however, several ferry operators had already lowered their prices and improved their services in order to compete. Today, both the tunnel and the ferries remain popular with travellers.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["Until","Now that","By the time","Unless","As long as"], a:2, e:"By the time + past simple → ana cümlede past perfect ve already = … olduğunda çoktan. Until “already” ile uyuşmaz; Now that ise geçmiş zaman anlatısında past perfect ile anlam kurmaz."},
  {id:"r-con-time-23", sub:"con-time", from:["conj-18"], q:"Tickets for the festival will go on sale ---- the dates of the concerts have been confirmed.", o:["as soon as","until","unless","while","whereas"], a:0, e:"as soon as = -er -mez; tarihler onaylanır onaylanmaz satış başlayacak (zaman cümlesinde will yerine present perfect). until satışı onaya kadar sürdürür ve anlamsızdır."},
  {id:"r-con-time-24", sub:"con-time", from:["conj-19","conj-20"], q:"The bridge has been closed to traffic ---- a crack was discovered in one of its supports last month.", o:["until","by the time","once","as soon as","since"], a:4, e:"since + past simple, ana cümlede present perfect = -den beri; köprü çatlak bulunduğundan beri kapalı. until ve by the time present perfect ana cümleyle ve “last month” ile uyuşmaz."},
  {id:"r-con-time-25", sub:"con-time", from:["conj-19"], q:"By the time the new manager ----, the company will have lost most of its best employees.", o:["will be appointed","is appointed","was appointed","had been appointed","would be appointed"], a:1, e:"By the time + present simple → ana cümlede future perfect (will have lost). Zaman cümlesinde will kullanılmaz; was/had been ise geçmiş zaman olduğundan future perfect ile uyuşmaz."},
  {id:"r-con-time-26", sub:"con-time", from:["w2-10"], q:"---- the new metro line is fully operational, commuters will continue to face long delays.", o:["Once","As soon as","Until","Now that","After"], a:2, e:"Until = -e kadar; gecikmeler metro hattı tam çalışana kadar sürecek (“continue” süreklilik bildirir). Once ve As soon as gecikmelerin metro açıldıktan sonra süreceğini söyler, mantıksızdır."},
  {id:"r-con-time-27", sub:"con-time", from:["conj-20"], q:"Now that the company ----, it no longer needs to rent office space from other firms.", o:["has built its own headquarters","will build its own headquarters","is going to build its own headquarters","had been building its own headquarters","would build its own headquarters"], a:0, e:"Now that tamamlanmış bir duruma dayanır: şirket kendi merkezini inşa etmiş (present perfect). will build ve is going to build gelecekteki bir eylemdir, “no longer needs” ile uyuşmaz."}
);
